{"argv": ["bash","-lc","python3 - <<'EOF'
import json, numpy as np, feat
from sklearn.ensemble import GradientBoostingRegressor, RandomForestRegressor, ExtraTreesRegressor

t=json.load(open('train.json'))
X={}; Y={}
for pid,rows in t.items():
    xs=[]; ys=[]
    for i in range(len(rows)):
        if rows[i]['core_temp'] is None: continue
        hist=[{k:v for k,v in r.items() if k!='core_temp'} for r in rows[:i+1]]
        xs.append(feat.extract(hist)); ys.append(rows[i]['core_temp'])
    X[pid]=np.array(xs); Y[pid]=np.array(ys)
pids=list(X)

def lopo_preds(make):
    preds={}
    for p in pids:
        Xtr=np.vstack([X[q] for q in pids if q!=p]); ytr=np.concatenate([Y[q] for q in pids if q!=p])
        m=make(); m.fit(Xtr,ytr)
        preds[p]=m.predict(X[p])
    return preds

def pb(preds):
    return np.mean([np.abs(preds[p]-Y[p]).mean() for p in pids])

cands={
 'rf_leaf2': lambda: RandomForestRegressor(n_estimators=500, min_samples_leaf=2, random_state=0, n_jobs=2),
 'rf_leaf5': lambda: RandomForestRegressor(n_estimators=500, min_samples_leaf=5, random_state=0, n_jobs=2),
 'rf_leaf10': lambda: RandomForestRegressor(n_estimators=500, min_samples_leaf=10, random_state=0, n_jobs=2),
 'et_leaf5': lambda: ExtraTreesRegressor(n_estimators=500, min_samples_leaf=5, random_state=0, n_jobs=2),
 'gbr_h': lambda: GradientBoostingRegressor(loss='huber', n_estimators=400, max_depth=3, learning_rate=0.05, subsample=0.8, random_state=0),
}
P={}
for name,make in cands.items():
    P[name]=lopo_preds(make)
    print(name, 'pbMAE=%.4f'%pb(P[name]))
# ensembles
import itertools
for combo in itertools.combinations(P,2):
    avg={p:(P[combo[0]][p]+P[combo[1]][p])/2 for p in pids}
    print('+'.join(combo), '%.4f'%pb(avg))
avg3={p:(P['rf_leaf5'][p]+P['et_leaf5'][p]+P['gbr_h'][p])/3 for p in pids}
print('rf+et+gbr', '%.4f'%pb(avg3))
np.save('/tmp/Y.npy', np.array([1]))
EOF"]}

