import pickle, numpy as np, feat
from sklearn.ensemble import ExtraTreesRegressor
X,Y=pickle.load(open('cache_xy.pkl','rb')); pids=list(X)
order=['rel_t30','rel_t','hrload_n','sqrt_t','hrload','t_hr','wt0','wt','bmi','wt_kg','mass','hr0','bsa','sk_rise','sk_e15']
idx=[feat.NAMES.index(n) for n in order]
def run(sel, leaf=56, tag=''):
    preds={}
    for p in pids:
        Xtr=np.vstack([X[q] for q in pids if q!=p])[:,sel]; ytr=np.concatenate([Y[q] for q in pids if q!=p])
        m=ExtraTreesRegressor(n_estimators=300, min_samples_leaf=leaf, random_state=0, n_jobs=2).fit(Xtr,ytr)
        preds[p]=m.predict(X[p][:,sel])
    pb=np.mean([np.abs(preds[p]-Y[p]).mean() for p in pids])
    print(tag,'pbMAE=%.4f'%pb, flush=True)
    return pb,preds
for k in [8,9,11,12]:
    run(idx[:k], tag=f'top{k}')
for leaf in [32,40,72,96]:
    run(idx[:10], leaf=leaf, tag=f'top10 leaf{leaf}')
