{"argv": ["bash","-lc","python3 - <<'EOF'
import pickle, numpy as np, feat
from sklearn.ensemble import ExtraTreesRegressor
X,Y=pickle.load(open('cache_xy.pkl','rb')); pids=list(X)
A=['rel_t30','hrload_n','hrload','t_hr','wt0','wt','bmi']
def run(names, leaf=56, seed=0):
    sel=[feat.NAMES.index(n) for n in names]
    preds={}
    for p in pids:
        Xtr=np.vstack([X[q] for q in pids if q!=p])[:,sel]; ytr=np.concatenate([Y[q] for q in pids if q!=p])
        m=ExtraTreesRegressor(n_estimators=300, min_samples_leaf=leaf, random_state=seed, n_jobs=2).fit(Xtr,ytr)
        preds[p]=m.predict(X[p][:,sel])
    return np.mean([np.abs(preds[p]-Y[p]).mean() for p in pids]), preds
for leaf in [40,56]:
    for seed in [0,1,2]:
        s,pr=run(A,leaf,seed); print('A leaf',leaf,'seed',seed,'%.4f'%s, flush=True)
        if leaf==56 and seed==0:
            pickle.dump(pr, open('cvpred_A56.pkl','wb'))
            maes={p:np.abs(pr[p]-Y[p]).mean() for p in pids}
            print({k:round(v,3) for k,v in sorted(maes.items())})
            res=np.concatenate([pr[p]-Y[p] for p in pids])
            print('q05,q95', np.round(np.percentile(res,[5,95]),3))
EOF"]}

